!function(){"use strict";var t="troolify_recent";function r(){try{var r=localStorage.getItem(t);return r?JSON.parse(r):[]}catch(t){return[]}}window.TroolifyRecent={record:function(e,n,c){if(e){var i=r();(i=i.filter(function(t){return t.href!==e})).unshift({href:e,name:n||"",icon:c||"fa-solid fa-wrench"}),i.length>5&&(i=i.slice(0,5)),function(r){try{localStorage.setItem(t,JSON.stringify(r))}catch(t){}}(i)}},get:function(){return r()}}}();